module tb_TopModule;
    logic clk;
    logic areset;
    logic in;
    logic out;

    TopModule uut (
        .clk(clk),
        .areset(areset),
        .in(in),
        .out(out)
    );

    // Clock generator
    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 0;
        in = 0;

        // Test asynchronous reset
        areset = 1;
        #3;
        areset = 0;

        // At reset, state should be A, out should be 0
        if (out !== 1'b0) begin
            $display("SELFTEST FAIL: Reset failed, out=%b", out);
            $finish;
        end

        // Sequence test:
        // A -> (in=1) -> B -> (in=1) -> B -> (in=0) -> C -> (in=1) -> D -> (out=1) -> (in=0) -> C -> (in=0) -> A

        // 1. A -> B (in=1)
        @(posedge clk);
        in = 1'b1;
        @(negedge clk);
        if (out !== 1'b0) begin $display("SELFTEST FAIL: state B out"); $finish; end

        // 2. B -> B (in=1)
        @(posedge clk);
        in = 1'b1;
        @(negedge clk);
        if (out !== 1'b0) begin $display("SELFTEST FAIL: state B->B out"); $finish; end

        // 3. B -> C (in=0)
        @(posedge clk);
        in = 1'b0;
        @(negedge clk);
        if (out !== 1'b0) begin $display("SELFTEST FAIL: state C out"); $finish; end

        // 4. C -> D (in=1)
        @(posedge clk);
        in = 1'b1;
        @(negedge clk);
        if (out !== 1'b1) begin $display("SELFTEST FAIL: state D out expected 1, got %b", out); $finish; end

        // 5. D -> C (in=0)
        @(posedge clk);
        in = 1'b0;
        @(negedge clk);
        if (out !== 1'b0) begin $display("SELFTEST FAIL: state C out expected 0, got %b", out); $finish; end

        // 6. C -> A (in=0)
        @(posedge clk);
        in = 1'b0;
        @(negedge clk);
        if (out !== 1'b0) begin $display("SELFTEST FAIL: state A out"); $finish; end

        // Test asynchronous reset mid-operation
        areset = 1;
        #2;
        if (out !== 1'b0) begin $display("SELFTEST FAIL: mid-op reset out"); $finish; end
        areset = 0;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    logic clk;
    logic areset;
    logic in;
    logic out;

    TopModule uut (
        .clk(clk),
        .areset(areset),
        .in(in),
        .out(out)
    );

    // Clock generator: 10 time units period
    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 0;
        in = 0;

        // Test asynchronous reset
        areset = 1;
        #3;
        areset = 0;
        #2;

        if (out !== 1'b0) begin
            $display("SELFTEST FAIL: Reset failed, out=%b", out);
            $finish;
        end

        // Table:
        // A | A(in=0), B(in=1) | 0
        // B | C(in=0), B(in=1) | 0
        // C | A(in=0), D(in=1) | 0
        // D | C(in=0), B(in=1) | 1

        // Start at A.
        // Test A -> B (in=1)
        @(negedge clk);
        in = 1'b1;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin $display("SELFTEST FAIL: A->B out"); $finish; end

        // Now in B. Test B -> B (in=1)
        @(negedge clk);
        in = 1'b1;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin $display("SELFTEST FAIL: B->B out"); $finish; end

        // Now in B. Test B -> C (in=0)
        @(negedge clk);
        in = 1'b0;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin $display("SELFTEST FAIL: B->C out"); $finish; end

        // Now in C. Test C -> D (in=1)
        @(negedge clk);
        in = 1'b1;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin $display("SELFTEST FAIL: C->D out, expected 1 got %b", out); $finish; end

        // Now in D. Test D -> C (in=0)
        @(negedge clk);
        in = 1'b0;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin $display("SELFTEST FAIL: D->C out, expected 0 got %b", out); $finish; end

        // Now in C. Test C -> A (in=0)
        @(negedge clk);
        in = 1'b0;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin $display("SELFTEST FAIL: C->A out"); $finish; end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

